import{_ as t,c as a,o as n,ag as i}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"🔄 Polling vs WebSockets — Real-Time Communication","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Communication_and_Security/What_is_polling_and_what_is_websocket_websockets_vs_polling.md","filePath":"senior_growth/Communication_and_Security/What_is_polling_and_what_is_websocket_websockets_vs_polling.md"}'),o={name:"senior_growth/Communication_and_Security/What_is_polling_and_what_is_websocket_websockets_vs_polling.md"};function r(s,e,l,d,c,h){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="🔄-polling-vs-websockets-—-real-time-communication" tabindex="-1">🔄 Polling vs WebSockets — Real-Time Communication <a class="header-anchor" href="#🔄-polling-vs-websockets-—-real-time-communication" aria-label="Permalink to “🔄 Polling vs WebSockets — Real-Time Communication”">​</a></h1><p>Modern web apps often need to <strong>receive updates from the server in real-time</strong>. Two common approaches are <strong>polling</strong> and <strong>WebSockets</strong>.</p><hr><h2 id="_1️⃣-polling" tabindex="-1">1️⃣ Polling <a class="header-anchor" href="#_1️⃣-polling" aria-label="Permalink to “1️⃣ Polling”">​</a></h2><h3 id="🔑-what-it-is" tabindex="-1">🔑 What It Is <a class="header-anchor" href="#🔑-what-it-is" aria-label="Permalink to “🔑 What It Is”">​</a></h3><p>Polling is a technique where the client <strong>repeatedly sends HTTP requests</strong> to the server at regular intervals to check for updates.</p><p><strong>Example:</strong> Use the <a href="./../../node-js/realtime-transports.html#completion-driven-polling-with-bounded-backoff">completion-driven scheduler</a>, whose next attempt starts only after the current attempt settles. Its owner cancels the request and timer; the adapter validates status, body and schema. Never turn an async request into an overlapping setInterval loop.</p><h3 id="✅-advantages" tabindex="-1">✅ Advantages <a class="header-anchor" href="#✅-advantages" aria-label="Permalink to “✅ Advantages”">​</a></h3><ul><li>Simple to implement.</li><li>Works with <strong>all browsers</strong> and standard HTTP.</li><li>No special server setup required.</li></ul><h3 id="❌-disadvantages" tabindex="-1">❌ Disadvantages <a class="header-anchor" href="#❌-disadvantages" aria-label="Permalink to “❌ Disadvantages”">​</a></h3><ul><li>High overhead → repeated requests/headers; transport connections can be reused or multiplexed.</li><li>Latency → updates are only received on the next poll.</li><li>Wastes server and network resources if data rarely changes.</li><li>Capacity depends on interval, conditional responses, request cost and active users; measure the actual workload.</li></ul><hr><h2 id="_2️⃣-websockets" tabindex="-1">2️⃣ WebSockets <a class="header-anchor" href="#_2️⃣-websockets" aria-label="Permalink to “2️⃣ WebSockets”">​</a></h2><h3 id="🔑-what-it-is-1" tabindex="-1">🔑 What It Is <a class="header-anchor" href="#🔑-what-it-is-1" aria-label="Permalink to “🔑 What It Is”">​</a></h3><p>WebSockets provide a <strong>persistent, full-duplex message channel</strong> (the common HTTP/1.1 upgrade uses TCP) between client and server.</p><ul><li>Client initiates handshake:</li></ul><p>Use the <a href="./RESTful_API_HTTP__and_WebSockets_-_why_and_when_we_need_them._Limitations.html#an-owned-browser-socket">owned socket example</a> for validation, cleanup and a bounded outbound queue.</p><ul><li>Server can push updates <strong>without waiting for the next poll</strong> whenever they occur.</li></ul><h3 id="✅-advantages-1" tabindex="-1">✅ Advantages <a class="header-anchor" href="#✅-advantages-1" aria-label="Permalink to “✅ Advantages”">​</a></h3><ul><li>Low application latency is possible; transport congestion and slow consumers still matter.</li><li>Bi-directional → client and server can send messages any time.</li><li>Efficient → single connection, no repeated headers.</li><li>Can reduce request overhead for frequent events, but needs connection and fan-out capacity planning.</li></ul><h3 id="❌-disadvantages-1" tabindex="-1">❌ Disadvantages <a class="header-anchor" href="#❌-disadvantages-1" aria-label="Permalink to “❌ Disadvantages”">​</a></h3><ul><li>More complex to implement on backend.</li><li>Stateful → harder to scale horizontally.</li><li>Some proxies/firewalls may block persistent connections.</li><li>Use WSS in production, plus authentication, authorization and exact Origin validation; encryption alone is insufficient.</li></ul><hr><h2 id="⚖️-polling-vs-websockets-—-comparison-table" tabindex="-1">⚖️ Polling vs WebSockets — Comparison Table <a class="header-anchor" href="#⚖️-polling-vs-websockets-—-comparison-table" aria-label="Permalink to “⚖️ Polling vs WebSockets — Comparison Table”">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Polling</th><th>WebSockets</th></tr></thead><tbody><tr><td>Connection</td><td>HTTP connection reuse/multiplexing possible</td><td>Persistent</td></tr><tr><td>Communication</td><td>Client requests; server responds</td><td>Bi-directional</td></tr><tr><td>Latency</td><td>High (depends on interval)</td><td>Low (real-time)</td></tr><tr><td>Efficiency</td><td>Depends on frequency/cache policy</td><td>Depends on fan-out and queue limits</td></tr><tr><td>Complexity</td><td>Simple</td><td>More complex</td></tr><tr><td>Scalability</td><td>Depends on request rate/cost</td><td>Depends on connection/fan-out capacity</td></tr><tr><td>Browser Support</td><td>Universal</td><td>Modern browsers</td></tr><tr><td>Security</td><td>HTTPS for production</td><td>WSS plus application security</td></tr><tr><td>Use Cases</td><td>Non-critical updates</td><td>Chat, live dashboards, notifications, games</td></tr></tbody></table><hr><h2 id="🧠-best-practices" tabindex="-1">🧠 Best Practices <a class="header-anchor" href="#🧠-best-practices" aria-label="Permalink to “🧠 Best Practices”">​</a></h2><ul><li><p>Use <strong>polling</strong> for:</p><ul><li>Infrequent updates</li><li>Legacy browsers</li><li>Simple apps where real-time data isn’t critical</li></ul></li><li><p>Use <strong>WebSockets</strong> for:</p><ul><li>Real-time applications (chat, notifications, live dashboards)</li><li>High-frequency updates</li><li>Bidirectional communication needs</li></ul></li><li><p><strong>Hybrid approach:</strong></p><ul><li>Initial load via REST/HTTP, real-time updates via WebSocket.</li></ul></li></ul><hr><blockquote><p><strong>Rule of Thumb:</strong> Polling → simple, low-frequency updates. WebSockets → efficient, real-time, high-frequency, bidirectional communication.</p></blockquote><h2 id="polling-exercise-and-debugging-evidence" tabindex="-1">Polling exercise and debugging evidence <a class="header-anchor" href="#polling-exercise-and-debugging-evidence" aria-label="Permalink to “Polling exercise and debugging evidence”">​</a></h2><p>Extract startPolling from the shared transport lesson into a scratch module. Supply a controllable load(signal) promise and fake clock. Hold the first request beyond two intervals: require one active request and no second timer-triggered load. Resolve it, advance less than the interval (still one request), then the full interval (second request). Abort while loading: the adapter must observe abort and the consumer must not receive a late value. Dispose twice; no timer or listener may survive.</p><p>Test terminal authentication/schema failure (stop), selected transient failure (bounded jitter), success resetting backoff, invalid delays, pre-aborted owner and a noncooperative adapter (document that cancellation cannot force an arbitrary promise to settle). Retry count/elapsed limits belong to a bounded job; a mounted live view intentionally runs until its owner stops. Use a real fetch adapter separately to test304 without JSON parsing, non-OK status, bounded body/schema parsing and timeout. Fake callbacks establish scheduler behavior, not browser network cancellation or proxy behavior.</p><p>Choose SSE for a one-way event feed when its reconnect/replay contract fits; choose WebSocket for sustained bidirectional messages. A low-frequency dashboard may be simpler with conditional polling. Preserve a stale/reconnecting/error UI rather than silently presenting old values as current.</p><p>References checked2026-10-22: <a href="https://nodejs.org/download/release/v24.18.0/docs/api/http.html" target="_blank" rel="noreferrer">Node24 HTTP keep-alive</a>, <a href="https://developer.mozilla.org/en-US/docs/Web/API/WebSocket" target="_blank" rel="noreferrer">WebSocket API</a>, <a href="https://developer.mozilla.org/en-US/docs/Web/API/AbortSignal" target="_blank" rel="noreferrer">AbortSignal</a>.</p>',35)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
